 const policy={record:expected,authority:GP_ACTIVATION_AUTHORITY,predecessor,acceptedGpGuardBlob:blob(acceptedBase,GP),inverses,retainedBlobs:Object.fromEntries([...output].filter(([p])=>!Object.hasOwn(inverses,p)).map(([p,s])=>[p,gpActivationGitBlob(s)])),expectedStatuses};
